import json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';p=H/(P+'_notes.json');n=json.loads(p.read_text())
rows={
507:('Full prompt/template JSON Schema in YAML defines lineage, guidance and string-embedded response schema; several records reject unknown fields.','Authority union with unrestricted string is open; embedded schema is not validated by a string type. Missing IDs/hash links, lineage acyclicity and policy compliance need host checks. Antibody extras and generation_id are unconstrained.'),
508:('Comparison schema names per-test, aggregate cost/token/latency/accuracy fields and nullable ratios.','Root has no required fields, so empty object is valid; negative metrics and arbitrary accuracy strings are admitted. No arithmetic or per-test/aggregate consistency, custody or denominator enforcement. Stored expected answers require dispatch blinding outside schema.'),
509:('Response schema distinguishes trial/evaluation/execution modes, raw response, parsed payload, sanitization, usage and receipt.','Raw reply is optional and receipt can be empty; optional digests/cryptographic authentication are not specified despite description. Enum unions with string remain open, counts/costs lack lower bounds and totals are not recomputed. Valid shape cannot certify checker verdict or spend.'),
510:('Pilot specification schema binds named coordinates, task/representation/model classifications and host-gate declarations; difficulty1–5, nonnegative spend/rewrite count and temperature0–2 are explicit.','Most enums are deliberately open string unions. Expected outcome and checker identifiers are claims, not executed predicates. Path references are unhashed/unconfined and test counts have no consistency checks; target spend is not reservation enforcement.'),
511:('Complete pilot type catalog maps specification,11 seed dialects, template/P-star, test plan, capsule, response and comparative result families to seven local schemas.','Catalog coverage/semantic equivalence are declarations. Opaque cipher without codebook does not preserve accessible task information; wrapping does not derive missing premises. Historical examples and shape taxonomy supply no fresh empirical evidence.'),
512:('Rewrite plan schema records prompt/seed references, expected outcome, counts and optional case/test lists.','No uniqueness, reference closure, count equality, nonnegative counters, equality of rewritten prompt or source hashing is enforced. Empty expected outcome is accepted; user_prompt_equals_rewritten_seed is only a Boolean assertion.'),
513:('Seed/rewrite schema records prompt and expected answer plus optional codebook/input typing; ten dialect subtype definitions are fully read.','Dialect subtype definitions are never referenced from root typing; carrier and grammar labels are unrestricted strings. Expected answers are co-located with input and must be excluded by dispatch caller. No actual syntax parser, semantic equality, finite-domain proof or source binding is supplied.'),
514:('Single-capsule test schema names expected/actual outcomes, nullable witness_verified and metrics; test index0–99 and generation nonnegative are bounded.','Actual and expected records may be empty; gate enum admits arbitrary string and authority is open. Negative spend/token counts and self-asserted witness status pass shape; no evidence hash or arithmetic correspondence.'),
520:('Fully read generated empty SPK template: separates syntax/arithmetic licenses, cycle/face distinctions, axiomatic proof from implementation tests, and narrows claim scope. Embedded output schema fixes SPK and requires summary/process fields with zero sections.','Explicitly not execution-ready. Persona/policy text cannot enforce mathematical admission or host authority; mass/self-model semantics are supplied stipulations. Empty-template sections are intentionally forbidden, not a generally reusable candidate certificate schema.'),
522:('Cochain representation declares rational cochains on finite vertices/edges/faces, total endpoint references, ordered slots and task role; triangle example has zero listed edge circulation.','No d matrices, orientations, nilpotence or Hodge operator is specified. Endpoint checks do not make a simplicial complex. Canonical source_id contains colon contrary to its own pattern; placeholder empty-string hashes do not bind the nonempty task.'),
523:('Diagram representation declares typed colors, boxes, wires and role spans with a simple IN→box→OUT example.','Listed invariants do not enforce planarity, acyclicity, port arity/order, unique consumption or monoidal equations. Example source_id violates its declared identifier regex; hashes are illustrative placeholders.'),
524:('Egraph representation names finite eclasses, rewrite strings, normal-form level and full constraint preservation target. It explicitly says the gate target has no measured numerator.','No congruence closure, saturation, rewrite soundness/confluence or span comparison algorithm occurs here. Declaring classes is not proving equality; canonical source_id violates the local regex.'),
525:('Operadic representation separates environment, signature skeleton and bound spans/ideals. Historical seven-record token total ratio is explicitly scoped, with unreplayed-provider and empty-text lexical-classifier caveats.','Strings naming ring/operations/ideals do not check operad laws, ring arithmetic or ideal closure. Canonical source_id violates local pattern; minimum operation/ideal existence rules are not enforced by array minItems in this custom specification.'),
526:('Raw representation states byte identity, equal digests, no injected framing and65536-byte ceiling, while explicitly declining unavailable empirical rate.','Canonical example is a rendered trial record rather than its declared representation object: source_text/representation_kind/authority absent. Digest equality alone is not byte comparison; hash/count enforcement belongs to owner.'),
527:('Relational representation supplies an actual SQLite STRICT DDL with primary key, NOT NULL role/text and role CHECK, plus prompt-span inserts.','Canonical INSERT example uses PostgreSQL-style ::text and double-quoted text, incompatible with claimed SQLite profile. Task existence, order, source reconstruction and untrusted SQL confinement are not established by DDL alone.'),
528:('Structured representation specifies sequential role segments, source reconstruction and canonical JSON claim with a concrete three-segment rendered example.','Custom required:true metadata is not standard JSON Schema. Exact serialization needs more than sorted keys/compact separators; hashes do not prove semantic role assignments. Example uses rendered prompt rather than declared payload object.'),
529:('Symbolic representation declares boundary grammar, exact wire/codebook key equality, task role and explicit unverified-role/no-authority legend.','Wire regex character class includes a space despite strict38-glyph alphabet. Regex alone does not enforce task existence, slot sequence, codebook equality or decoding. Canonical example is rendered prompt, omitting declared structured wire/grammar fields.'),
533:('Raw prompt JSON Schema requires schema constant, prompt ID/content hash shapes, nonempty user text and None authority.','Neither hash is recomputed or related to text; source whitespace, system/user binding and meaning are outside shape validation. Nonempty string still permits whitespace-only input.'),
}
for i,(a,l)in rows.items():n[str(i)]={'assessment':a,'limits':l}
p.write_text(json.dumps(n,indent=2)+'\n')
